import numpy as np
rng=np.random.default_rng(937)
l=np.array([-2.,-1.,1.,2.]); s=2

def step(w):
    V=np.column_stack([l**j for j in range(s)])
    c=np.linalg.solve(V.T@(w[:,None]*V),-V.T@(w*l**s))
    q=l**s+V@c;h=w@(q*q)
    return w*q*q/h

target=np.ones(4)/4
worst={key:(-1,None) for key in ['hilbert','KL','revKL','sqrt']}
for k in range(10000):
    w=np.exp(rng.normal(size=4));w/=sum(w)
    z=step(step(w))
    def vals(w):
        r=w/target
        return {'hilbert':np.ptp(np.log(r)),'KL':-target@np.log(r),'revKL':w@np.log(r),'sqrt':np.sum((np.sqrt(w)-np.sqrt(target))**2)}
    a,b=vals(w),vals(z)
    for key in a:
        d=b[key]-a[key]
        if d>worst[key][0]:worst[key]=(d,w)
print(worst)

